// ============================================================
// Parsear SQL (Groq)
// ------------------------------------------------------------
// Extrae {sqlQuery, thoughts} de la respuesta JSON del LLM y
// propaga el contexto completo (incluyendo startTime).
// ============================================================

const promptCtx = $('Construir Prompt SQL').item.json;
const groqResponse = $input.item.json;

const contentString = groqResponse?.choices?.[0]?.message?.content;
if (!contentString) {
  throw new Error('Groq response did not contain choices[0].message.content');
}

let parsedContent;
try {
  parsedContent = JSON.parse(contentString);
} catch (error) {
  throw new Error(`Error parsing Groq response JSON: ${error.message}. Content: ${contentString}`);
}

const sqlQuery = (parsedContent.sqlQuery || '').trim();
const thoughts = Array.isArray(parsedContent.thoughts) ? parsedContent.thoughts : [];

if (!sqlQuery) {
  throw new Error(`No SQL query found. Parsed: ${JSON.stringify(parsedContent)}`);
}

return {
  ...promptCtx,
  sqlQuery,
  thoughts
};

// ============================================================
// Validar SQL (guardrails)
// ------------------------------------------------------------
// Guardrails de seguridad y corrección sobre el SQL generado
// por el LLM antes de ejecutarlo contra Postgres:
//   - Debe empezar por SELECT.
//   - Prohíbe DDL/DML, multisentencia y comentarios peligrosos.
//   - Fuerza LIMIT máximo 10.
//
// Nota: `executeQuery` de n8n devuelve las filas del último
// statement, por lo que mantenemos UNA única sentencia SELECT.
// El statement_timeout debe configurarse a nivel de credencial
// de Postgres (DB role con timeout por defecto).
// ============================================================

const data = $input.item.json;
let query = (data.sqlQuery || '').trim();

if (!query) {
  throw new Error('sqlQuery vacío tras parseo');
}

// 1. Normalizar: quitar punto y coma final + comentarios de línea.
query = query.replace(/;\s*$/g, '').replace(/--.*$/gm, '').trim();

// 2. Solo debe haber una sentencia.
if (query.includes(';')) {
  throw new Error(`SQL rechazado: múltiples sentencias detectadas.`);
}

// 3. Debe empezar por SELECT.
if (!/^\s*select\b/i.test(query)) {
  throw new Error(`SQL rechazado: no empieza por SELECT. Query: ${query.slice(0, 120)}`);
}

// 4. Lista de bloqueo de keywords destructivas.
const forbidden = [
  'insert', 'update', 'delete', 'drop', 'alter', 'truncate',
  'create', 'grant', 'revoke', 'merge', 'replace', 'copy',
  'call', 'execute', 'vacuum', 'analyze', 'pg_read_file',
  'pg_write_file', 'pg_sleep'
];
const lowered = query.toLowerCase();
for (const bad of forbidden) {
  // \b garantiza palabra completa (evita falsos positivos tipo "updated_at").
  const re = new RegExp(`\\b${bad}\\b`);
  if (re.test(lowered)) {
    throw new Error(`SQL rechazado: contiene keyword prohibido "${bad}".`);
  }
}

// 5. Forzar LIMIT máximo 10.
if (!/\blimit\s+\d+/i.test(query)) {
  query = `${query}\nLIMIT 10`;
} else {
  query = query.replace(/\blimit\s+(\d+)/i, (_, n) => `LIMIT ${Math.min(Number(n) || 10, 10)}`);
}

return {
  ...data,
  sqlQuery: query,
  sqlQueryRaw: query
};

// ============================================================
// Normalizar Libros
// ------------------------------------------------------------
// Recoge los items devueltos por Postgres, los mapea al shape
// que consume el prompt de respuesta y conserva IDs numéricos
// únicos (se usan luego para validar las recommendations del LLM).
//
// Robustez: Postgres viene con retryOnFail + alwaysOutputData +
// continueOnFail, por lo que puede llegar:
//   - Sin filas (error o simplemente 0 resultados) → items vacíos o
//     con { error, ... }.
//   - Con filas válidas.
// Marcamos `needsFallback: true` si no hay libros válidos para que
// el IF posterior dispare la query de respaldo en lugar de reventar.
// ============================================================

const sqlResults = $input.all();
const previousData = $('Validar SQL (guardrails)').first().json;

const books = [];
const seen = new Set();

for (const row of sqlResults) {
  const j = row?.json;
  // Si Postgres falla (continueOnFail) devuelve items con `error` o vacíos.
  if (!j || j.error) continue;
  const id = Number(j.id);
  if (!Number.isFinite(id) || id <= 0 || seen.has(id)) continue;
  seen.add(id);
  books.push({
    id,
    title: j.title,
    author: j.author,
    description: j.description,
    coverUrl: j.cover_url || j.cover_image || null
  });
}

return [{
  json: {
    userId: previousData.userId,
    conversationId: previousData.conversationId,
    messageId: previousData.messageId,
    userMessage: previousData.userMessage,
    baseUrl: previousData.baseUrl,
    intentType: previousData.intentType,
    intentConfidence: previousData.intentConfidence,
    mode: previousData.mode || 'chat',
    maxItems: previousData.maxItems || null,
    conversationContext: previousData.conversationContext || [],
    sqlQuery: previousData.sqlQueryRaw,
    sqlThoughts: previousData.thoughts,
    listaLibros: books,
    candidateIds: Array.from(seen),
    needsFallback: books.length === 0,
    startTime: previousData.startTime
  }
}];

// ============================================================
// Normalizar Libros Fallback
// ------------------------------------------------------------
// Se dispara cuando el SQL inicial (del LLM) no devolvió nada o
// falló tras sus 3 reintentos automáticos. Ejecutamos antes una
// query genérica `SQL Fallback` (aleatoria sobre catalog_books no
// comprados por el usuario) con su propio retry automático.
//
// Aquí reusamos el contexto ya preparado en `Normalizar Libros`
// (userId, conversationId, conversationContext, mode, etc.) y solo
// reemplazamos `listaLibros` / `candidateIds` con las filas del
// fallback. Si el fallback también devolvió vacío, `listaLibros`
// queda [] pero el flujo continúa: el LLM responderá una disculpa
// cordial en vez de romper la ejecución.
// ============================================================

const sqlResults = $input.all();
const previousData = $('Normalizar Libros').first().json;

const books = [];
const seen = new Set();

for (const row of sqlResults) {
  const j = row?.json;
  if (!j || j.error) continue;
  const id = Number(j.id);
  if (!Number.isFinite(id) || id <= 0 || seen.has(id)) continue;
  seen.add(id);
  books.push({
    id,
    title: j.title,
    author: j.author,
    description: j.description,
    coverUrl: j.cover_url || j.cover_image || null
  });
}

return [{
  json: {
    ...previousData,
    listaLibros: books,
    candidateIds: Array.from(seen),
    needsFallback: false,
    usedFallback: true,
    sqlThoughts: [
      ...(previousData.sqlThoughts || []),
      `Fallback aplicado: el SQL original no devolvió resultados. Usada query genérica (${books.length} libros).`
    ]
  }
}];

// ============================================================
// Construir Prompt Respuesta
// ------------------------------------------------------------
// Compone el prompt que genera la respuesta Markdown al usuario y
// pide al LLM que marque explícitamente los `bookIds` (se validan
// contra `candidateIds` en el post-proceso).
//
// DISEÑO (H2.3): el frontend ya renderiza tarjetas bonitas con la
// portada, título y autor de cada libro recomendado a partir de
// `metadata.recommendations`. Por eso aquí el LLM NO debe incluir
// imágenes ni enlaces "Ver ficha" ni repetir cada libro con su
// portada: quedaría duplicado y feo. Solo genera texto limpio:
// saludo + intro + mini-resumen de 1-2 frases por libro + cierre.
//
// Primera interacción: además pedimos `suggestedTitle` para no
// dejar la conversación como "Nueva conversación".
// ============================================================

const data = $input.item.json;

// ¿Primera interacción? (solo hay 1 mensaje del usuario en el contexto).
const previousUserMessages = (data.conversationContext || []).filter((m) => m.role === 'user').length;
const isFirstInteraction = previousUserMessages <= 1;

const isPlaylistBuilder = data.mode === 'playlist_builder';
const maxItems = isPlaylistBuilder ? (Number(data.maxItems) || 8) : 5;

// ============================================================
// Prompt de sistema
// ============================================================
const systemPromptChat = `Eres un asistente experto en recomendación de libros, amigable y cálido.

RESPONDE EN FORMATO JSON EXACTO (sin texto extra, sin \`\`\`):
{
  "thoughts": ["análisis del mensaje", "criterios de selección", "razonamiento breve"],
  "response": "Tu respuesta final en Markdown limpio",
  "bookIds": [12, 45, 78]${isFirstInteraction ? ',\n  "suggestedTitle": "Título muy corto (3-6 palabras) que resuma de qué va esta conversación"' : ''}
}

REGLAS DE "bookIds":
- Solo enteros tomados de la lista "LIBROS DISPONIBLES".
- Máximo ${maxItems} recomendaciones. Puedes devolver menos si no hay suficientes coincidencias.
- No inventes IDs ni libros.

REGLAS DE "response" (¡MUY IMPORTANTES!):
- Texto en español, tono natural y cercano (no robótico, no corporativo).
- Markdown estricto. NADA de HTML.
- NO incluyas imágenes. El frontend ya muestra las portadas en tarjetas.
- NO incluyas enlaces "Ver ficha" ni URLs a "/book-details/...".
- NO uses tablas, no uses bloques de código.
- Longitud objetivo: 80-160 palabras en total. Sé conciso.

FORMATO RECOMENDADO DEL CAMPO "response":
1. Una o dos frases de saludo y puente, empatizando con lo que pide el usuario.
2. Una lista numerada con los libros recomendados. Formato por línea:
   "1. **{Título}** — *{Autor}*: una frase breve (máx. 20 palabras) explicando por qué encaja con la petición."
3. (Opcional) Una frase final de cierre o pregunta abierta invitando a refinar la búsqueda.
${isFirstInteraction ? '\nREGLAS DE "suggestedTitle":\n- 3-6 palabras, SIN comillas y SIN puntuación final.\n- Debe reflejar la temática concreta que pide el usuario (género, autor, estado de ánimo, etc.).\n- Evita títulos genéricos como "Recomendaciones", "Libros", "Nueva conversación".\n' : ''}
IDIOMA:
- Responde SIEMPRE en el idioma del último mensaje del usuario (español por defecto).`;

// Variante para MODO PLAYLIST: la IA actúa de co-curadora. Devuelve un
// `playlistDraft` estructurado que el frontend renderiza en un panel
// visual (portadas, orden, nota por libro). La conversación mantiene un
// único borrador: cada turno devuelve el borrador ACTUALIZADO completo.
const systemPromptPlaylist = `Eres una co-curadora experta de playlists de libros en BookMatch.

MODO: PLAYLIST_BUILDER. El usuario y tú estáis montando UNA playlist concreta a través de conversación.
Cada turno devuelves el borrador COMPLETO y actualizado (no solo los cambios).

RESPONDE EN FORMATO JSON EXACTO (sin \`\`\`, sin texto extra):
{
  "thoughts": ["breve análisis de lo que pide el usuario", "criterios", "cambios respecto al borrador anterior"],
  "response": "Tu respuesta conversacional en Markdown breve (60-120 palabras). Explica qué has incluido o cambiado y pregunta si quiere ajustar algo (quitar, añadir, reordenar, cambiar tono).",
  "bookIds": [12, 45, 78, ...],
  "playlistDraft": {
    "title": "Título de la playlist (3-6 palabras)",
    "description": "Descripción de 1-2 frases sobre la vibra de la playlist",
    "items": [
      { "catalogBookId": 12, "note": "Frase corta (máx 20 palabras) sobre por qué este libro encaja" },
      ...
    ]
  }${isFirstInteraction ? ',\n  "suggestedTitle": "Título corto (3-6 palabras) para esta conversación"' : ''}
}

REGLAS DE "bookIds" y "playlistDraft.items":
- Exactamente ${maxItems} libros por defecto, salvo que el usuario pida más o menos explícitamente.
- Solo IDs presentes en "LIBROS DISPONIBLES".
- El ORDEN del array es el orden final de la playlist (primero = posición 1).
- No repitas libros. Cada catalogBookId aparece una sola vez.
- "note" es una descripción corta del papel del libro en la playlist (no lo confundas con la sinopsis del libro).

REGLAS DE "response":
- Markdown limpio. NO listes los libros uno a uno (el panel visual los muestra).
- Céntrate en explicar la curación: "He abierto con X para marcar el tono, y cerrado con Y para un golpe final."
- Termina invitando a iterar: "¿Cambiamos el cierre?", "¿Más thriller o más introspección?".
- NO imágenes, NO enlaces, NO tablas.

REGLAS DE "playlistDraft.title":
- 3-6 palabras, evocador, sin comillas ni puntuación final.

${isFirstInteraction ? 'REGLAS DE "suggestedTitle":\n- Mismo estilo que playlistDraft.title pero para nombrar la CONVERSACIÓN.\n\n' : ''}IDIOMA:
- Responde SIEMPRE en el idioma del último mensaje del usuario (español por defecto).`;

const systemPrompt = isPlaylistBuilder ? systemPromptPlaylist : systemPromptChat;

const userPrompt = `CONTEXTO DE LA CONVERSACIÓN (últimos mensajes):
${JSON.stringify(data.conversationContext || [])}

MENSAJE DEL USUARIO:
${data.userMessage}

LIBROS DISPONIBLES (elige solo de aquí; cada uno trae id, title, author, description):
${JSON.stringify(data.listaLibros)}

ANÁLISIS PREVIO (del paso SQL):
${JSON.stringify(data.sqlThoughts || [])}

${isPlaylistBuilder ? `OBJETIVO: Construye una playlist de ~${maxItems} libros y devuelve el borrador ACTUALIZADO COMPLETO en "playlistDraft".` : 'GENERA AHORA EL JSON.'}`;

return {
  ...data,
  isFirstInteraction,
  isPlaylistBuilder,
  maxItems,
  responsePrompt: JSON.stringify({
    model: 'llama-3.3-70b-versatile',
    temperature: 0.7,
    // En modo playlist necesitamos más tokens (array grande de items con notas).
    max_tokens: isPlaylistBuilder ? 2000 : 1200,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ]
  })
};

// ============================================================
// Procesar Respuesta IA
// ------------------------------------------------------------
// - Parsea el JSON del LLM (thoughts, response, bookIds).
// - Normaliza recommendations a enteros positivos únicos.
// - Filtra contra `candidateIds` (los IDs REALES devueltos por
//   el SQL) para descartar alucinaciones.
// - Fallback: si no queda ninguno, toma los 5 primeros del SQL.
// - Mide processingTime end-to-end (desde el webhook).
// ============================================================

const previous = $('Construir Prompt Respuesta').item.json;
const groqResponse = $input.item.json;
const raw = groqResponse?.choices?.[0]?.message?.content?.trim() ?? '';

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (error) {
  console.error('Error parsing response JSON:', error);
  parsed = { thoughts: ['Error al generar thoughts estructurados'], response: raw, bookIds: [] };
}

const candidateIds = new Set((previous.candidateIds || []).map((id) => Number(id)));
const isPlaylistBuilder = previous.isPlaylistBuilder === true;
const maxItems = Number(previous.maxItems) || (isPlaylistBuilder ? 8 : 5);

// Normaliza bookIds del LLM a enteros positivos únicos y los intersecta con candidateIds.
const seen = new Set();
const validated = [];
for (const value of parsed.bookIds || []) {
  const id = typeof value === 'number' ? value : Number(value);
  if (!Number.isFinite(id) || id <= 0) continue;
  if (!candidateIds.has(id)) continue;
  if (seen.has(id)) continue;
  seen.add(id);
  validated.push(id);
}

// Fallback: si el LLM no devolvió nada usable, tomamos los primeros del SQL.
let recommendations = validated;
if (recommendations.length === 0 && previous.listaLibros?.length) {
  recommendations = previous.listaLibros.slice(0, maxItems).map((b) => Number(b.id));
}

// En modo playlist, recortamos a maxItems para que la playlist no se desborde.
if (isPlaylistBuilder && recommendations.length > maxItems) {
  recommendations = recommendations.slice(0, maxItems);
}

// --- Borrador de playlist (solo si el LLM lo pidió en modo playlist_builder) ---
let playlistDraft = null;
if (isPlaylistBuilder) {
  const rawDraft = parsed.playlistDraft || {};
  const items = [];
  const seenDraft = new Set();
  const rawItems = Array.isArray(rawDraft.items) ? rawDraft.items : [];
  for (const rawItem of rawItems) {
    if (items.length >= maxItems) break;
    const id = typeof rawItem.catalogBookId === 'number'
      ? rawItem.catalogBookId
      : Number(rawItem.catalogBookId);
    if (!Number.isFinite(id) || id <= 0) continue;
    if (!candidateIds.has(id)) continue;
    if (seenDraft.has(id)) continue;
    seenDraft.add(id);
    const note = typeof rawItem.note === 'string' ? rawItem.note.trim().slice(0, 200) : null;
    items.push({
      catalogBookId: id,
      position: items.length + 1,
      note: note || null
    });
  }

  // Si el LLM no devolvió items válidos pero sí recommendations,
  // sintetizamos un borrador mínimo para no romper el panel del frontend.
  if (items.length === 0 && recommendations.length > 0) {
    recommendations.forEach((id, idx) => {
      items.push({ catalogBookId: id, position: idx + 1, note: null });
    });
  }

  const draftTitle = typeof rawDraft.title === 'string' ? rawDraft.title.trim() : '';
  const draftDesc = typeof rawDraft.description === 'string' ? rawDraft.description.trim() : '';
  playlistDraft = {
    title: draftTitle.slice(0, 100) || 'Playlist en construcción',
    description: draftDesc.slice(0, 500) || '',
    items
  };
}

const allThoughts = [
  ...(previous.sqlThoughts || []).map((t) => `[SQL] ${t}`),
  ...(parsed.thoughts || []).map((t) => `[Response] ${t}`)
];

const startedAt = previous.startTime || Date.now();

// Sanear suggestedTitle solo si se pidió (primera interacción).
// Limitamos a 60 caracteres y eliminamos comillas y signos finales ruidosos.
function sanitizeTitle(raw) {
  if (!raw || typeof raw !== 'string') return null;
  let t = raw.trim().replace(/^["'«»]+|["'«»]+$/g, '').replace(/[.…]+$/, '').trim();
  if (!t) return null;
  if (t.length > 60) t = t.slice(0, 60).trim() + '…';
  return t;
}
const conversationTitle = previous.isFirstInteraction ? sanitizeTitle(parsed.suggestedTitle) : null;

return {
  userId: previous.userId,
  conversationId: previous.conversationId,
  messageId: previous.messageId,
  content: parsed.response || raw,
  conversationTitle,
  metadata: {
    thoughts: allThoughts,
    recommendations,
    used_querys: [previous.sqlQuery],
    intentType: 'book_recommendation',
    intentConfidence: previous.intentConfidence ?? null,
    processingTime: Date.now() - startedAt,
    mode: previous.mode || 'chat',
    ...(playlistDraft ? { playlistDraft } : {})
  }
};

// ============================================================
// Construir Prompt Casual
// ------------------------------------------------------------
// Prompt más ligero para chat casual (saludos, agradecimientos).
// Ahora también recibe contexto previo (memoria) y, si es el
// primer mensaje del usuario, pide al LLM un `suggestedTitle`.
// ============================================================

const data = $input.item.json;

// Si el contexto normalizado está vacío (o solo contiene el mensaje actual
// del usuario) significa que es la primera interacción → pedimos título.
const previousUserMessages = (data.conversationContext || []).filter((m) => m.role === 'user').length;
const isFirstInteraction = previousUserMessages <= 1;

const systemPrompt = `Eres un asistente amigable de una librería online llamada BookMatch.

RESPONDE SIEMPRE EN FORMATO JSON EXACTO (sin \`\`\`, sin texto extra):
{
  "thoughts": ["observación breve 1", "observación breve 2"],
  "response": "Tu respuesta final en Markdown breve y cálido"${isFirstInteraction ? ',\n  "suggestedTitle": "Título muy corto (3-6 palabras) para esta conversación"' : ''}
}

REGLAS:
- Tono natural y cercano, en español.
- Máximo 60 palabras en "response".
- Menciona de pasada que también puedes recomendar libros.
- NO uses imágenes ni enlaces.${isFirstInteraction ? '\n- "suggestedTitle": 3-6 palabras, sin comillas, sin puntuación final. Resume el tono o tema del saludo (p.ej. "Saludo inicial", "Primer contacto").' : ''}`;

const userPrompt = `CONTEXTO DE LA CONVERSACIÓN (últimos mensajes):
${JSON.stringify(data.conversationContext || [])}

MENSAJE DEL USUARIO:
${data.userMessage}

Genera ahora el JSON.`;

return {
  ...data,
  isFirstInteraction,
  casualPrompt: JSON.stringify({
    model: 'llama-3.3-70b-versatile',
    temperature: 0.7,
    max_tokens: 350,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ]
  })
};

// ============================================================
// Procesar Casual Chat
// ------------------------------------------------------------
// Extrae thoughts y response del JSON del LLM y mide el
// processingTime end-to-end.
// ============================================================

const previous = $('Construir Prompt Casual').item.json;
const groqResponse = $input.item.json;
const raw = groqResponse?.choices?.[0]?.message?.content?.trim() ?? '';

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (error) {
  parsed = { thoughts: ['Respuesta casual generada'], response: raw };
}

const startedAt = previous.startTime || Date.now();

function sanitizeTitle(raw) {
  if (!raw || typeof raw !== 'string') return null;
  let t = raw.trim().replace(/^["'«»]+|["'«»]+$/g, '').replace(/[.…]+$/, '').trim();
  if (!t) return null;
  if (t.length > 60) t = t.slice(0, 60).trim() + '…';
  return t;
}
const conversationTitle = previous.isFirstInteraction ? sanitizeTitle(parsed.suggestedTitle) : null;

return {
  userId: previous.userId,
  conversationId: previous.conversationId,
  messageId: previous.messageId,
  content: parsed.response || raw,
  conversationTitle,
  metadata: {
    thoughts: parsed.thoughts || [],
    recommendations: [],
    used_querys: [],
    intentType: 'casual_chat',
    intentConfidence: previous.intentConfidence ?? null,
    processingTime: Date.now() - startedAt
  }
};

// ============================================================
// Respuesta Out of Scope
// ------------------------------------------------------------
// Devuelve una respuesta estática pero preserva metadata
// coherente (incluido processingTime e intentConfidence).
// ============================================================

const data = $input.item.json;
const startedAt = data.startTime || Date.now();

return {
  userId: data.userId,
  conversationId: data.conversationId,
  messageId: data.messageId,
  content: 'Lo siento, solo puedo ayudarte con recomendaciones de libros y preguntas relacionadas con nuestra biblioteca. ¿Puedo ayudarte a encontrar algún libro?',
  metadata: {
    thoughts: ['Mensaje fuera del alcance del asistente'],
    recommendations: [],
    used_querys: [],
    intentType: 'out_of_scope',
    intentConfidence: data.intentConfidence ?? null,
    processingTime: Date.now() - startedAt
  }
};

